else if (programa.includes('Summer Camp')) parte1 = FASE1.summer;
else if (programa.includes('Pathway')) parte1 = FASE1.pathway;
else if (programa.includes('Gap Year')) parte1 = FASE1.gap_year;

const mcBody = {
  subscriber_id: Number(id_manychat),
